 static void Empty(Inventory bag){for(int i=0;i<bag.items.Count;i++)bag.items[i]=null;bag.NotifyExchange();}
 static void Move(GameObject player,Vector3 position){var cc=player.GetComponent<CharacterController>();if(cc!=null)cc.enabled=false;player.transform.position=position;if(cc!=null)cc.enabled=true;Physics.SyncTransforms();}
